module rtl_checker #(
    parameter integer W = 2,
    parameter integer DEPTH = 4
) (
    input logic clk,
    input logic rst,
    input logic wr_en,
    input logic [W-1:0] din,
    input logic rd_en,
    input logic [W-1:0] dout,
    input logic full,
    input logic empty,
    input logic [$clog2(DEPTH):0] count
);
    // Monitor state: model of FIFO after the previous edge.
    logic [W-1:0] mem [0:DEPTH-1];
    integer cnt = 0;
    logic valid = 1'b0;          // reset has established the starting state
    logic last_read = 1'b0;      // successful read on preceding transition
    logic [W-1:0] exp_dout = '0;

    integer i;
    integer n;
    logic do_rd;
    logic do_wr;

    always @(posedge clk) begin
        // Checks against state produced by the previous edge
        if (valid) begin
            assert (count == cnt);
            assert (empty == (cnt == 0));
            assert (full == (cnt == DEPTH));
            if (last_read) begin
                assert (dout == exp_dout);
            end
        end

        // Model update using this edge's inputs
        if (rst) begin
            cnt = 0;
            valid = 1'b1;
            last_read = 1'b0;
        end else if (valid) begin
            n = cnt;
            do_rd = rd_en && (cnt != 0);
            do_wr = wr_en && (cnt != DEPTH);
            last_read = do_rd;
            if (do_rd) begin
                exp_dout = mem[0];
                for (i = 0; i < DEPTH-1; i = i + 1)
                    mem[i] = mem[i+1];
                n = n - 1;
            end
            if (do_wr) begin
                mem[n] = din;
                n = n + 1;
            end
            cnt = n;
        end
    end
endmodule

module rtl_checker #(
    parameter integer W = 2,
    parameter integer DEPTH = 4
) (
    input logic clk,
    input logic rst,
    input logic wr_en,
    input logic [W-1:0] din,
    input logic rd_en,
    input logic [W-1:0] dout,
    input logic full,
    input logic empty,
    input logic [$clog2(DEPTH):0] count
);
    logic [W-1:0] mem [0:DEPTH-1];
    integer cnt;
    logic valid;
    logic last_rd_valid;
    logic [W-1:0] last_rd_data;

    integer i;
    integer pos;
    logic do_wr;
    logic do_rd;

    initial begin
        cnt = 0;
        valid = 1'b0;
        last_rd_valid = 1'b0;
        last_rd_data = '0;
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = '0;
    end

    always @(posedge clk) begin
        // Checks against state produced by the previous edge
        if (valid) begin
            assert (count == cnt);
            assert (full == (cnt == DEPTH));
            assert (empty == (cnt == 0));
            if (last_rd_valid) begin
                assert (dout == last_rd_data);
            end
        end

        // Monitor update using the inputs sampled at this edge
        if (rst) begin
            cnt = 0;
            valid = 1'b1;
            last_rd_valid = 1'b0;
        end else begin
            do_wr = wr_en && (cnt != DEPTH);
            do_rd = rd_en && (cnt != 0);
            last_rd_valid = do_rd;
            if (do_rd) begin
                last_rd_data = mem[0];
                for (i = 0; i < DEPTH-1; i = i + 1) mem[i] = mem[i+1];
                cnt = cnt - 1;
            end
            if (do_wr) begin
                pos = cnt;
                mem[pos] = din;
                cnt = cnt + 1;
            end
        end
    end
endmodule

module rtl_checker (
    input logic [15:0] x,
    input logic [4:0] count
);
    logic [4:0] expected;

    always_comb begin
        expected = 5'd0;
        for (int i = 0; i < 16; i++) begin
            expected = expected + {4'd0, x[i]};
        end
        assert (count == expected);
    end
endmodule

module rtl_checker (
    input logic [15:0] x,
    input logic [4:0] count
);
    logic [4:0] expected;

    always_comb begin
        expected = 5'd0;
        for (int i = 0; i < 16; i++) begin
            expected = expected + {4'd0, x[i]};
        end
        assert (count == expected);
        assert (count <= 5'd16);
    end
endmodule

module rtl_checker (
    input logic clk,
    input logic rst,
    input logic [3:0] req,
    input logic [3:0] gnt
);
    logic       valid   = 1'b0;
    logic [1:0] cursor  = 2'd0;
    logic [3:0] exp_gnt = 4'd0;

    logic [1:0] idx;
    logic       found;
    logic [1:0] win;
    logic [3:0] n_gnt;
    logic [1:0] n_cursor;

    always @(posedge clk) begin
        // Check the registered output produced by the previous edge.
        if (valid) begin
            assert (gnt == exp_gnt);
        end

        // Update the monitor state, which mirrors the implementation's update.
        if (rst) begin
            valid   <= 1'b1;
            cursor  <= 2'd0;
            exp_gnt <= 4'd0;
        end else if (valid) begin
            found = 1'b0;
            win   = 2'd0;
            for (int i = 0; i < 4; i++) begin
                idx = cursor + i[1:0];
                if (!found && req[idx]) begin
                    found = 1'b1;
                    win   = idx;
                end
            end
            if (found) begin
                n_gnt = 4'd0;
                n_gnt[win] = 1'b1;
                n_cursor = win + 2'd1;
                exp_gnt <= n_gnt;
                cursor  <= n_cursor;
            end else begin
                exp_gnt <= 4'd0;
            end
        end
    end
endmodule

module rtl_checker (
    input logic clk,
    input logic rst,
    input logic [3:0] req,
    input logic [3:0] gnt
);
    logic       valid   = 1'b0;   // set once a reset edge has established the starting state
    logic [1:0] cursor  = 2'd0;   // expected priority cursor
    logic [3:0] exp_gnt = 4'd0;   // expected registered grant (as observed at the next edge)

    logic [1:0] idx;
    logic       found;
    logic [1:0] win;
    integer     i;

    always @(posedge clk) begin
        // Check observed registered grant against the model (pre-update state)
        if (valid) begin
            assert (gnt == exp_gnt);
            assert ((gnt & (gnt - 4'd1)) == 4'd0); // one-hot or zero
        end

        // Update the model using the inputs sampled at this edge
        if (rst) begin
            valid   <= 1'b1;
            cursor  <= 2'd0;
            exp_gnt <= 4'd0;
        end else if (valid) begin
            found = 1'b0;
            win   = 2'd0;
            for (i = 0; i < 4; i = i + 1) begin
                idx = cursor + i[1:0];
                if (!found && req[idx]) begin
                    found = 1'b1;
                    win   = idx;
                end
            end
            if (found) begin
                exp_gnt <= (4'b0001 << win);
                cursor  <= win + 2'd1;
            end else begin
                exp_gnt <= 4'd0;
                cursor  <= cursor;
            end
        end
    end
endmodule
